y_opt = []
y_worst = []

for i in range(15, 35):
    opt_values = data_2[f"d_opt{i}"]
    worst_values = data_2[f"d_worst{i}"]
    sum_opt = 0
    sum_worst = 0
    for t in range(5):
        sum_opt += opt_values[t][0]
        sum_worst += worst_values[t][0]
    y_opt += [sum_opt / 5]
    y_worst += [sum_worst / 5]

fig, ax = plt.subplots(figsize=(9, 7))

ax.plot(range(15,35), y_opt, "red", label="optimal case")
ax.plot(range(15,35), y_worst, label="worst case")
ax.set_title(
    f"benchmarks on functional rbt implementation"
)
ax.set_xlabel("depth")
ax.set_ylabel("run time (seconds)")
ax.set_xticks(range(15, 35))
ax.legend()

plt.show()